import{c as s,Q as n,j as o,m as l}from"./chunks/framework.rWdQudnF.js";const d=JSON.parse('{"title":"架构设计 错题本","description":"","frontmatter":{"title":"架构设计 错题本"},"headers":[],"relativePath":"综合知识/架构设计/架构设计 重要背诵/架构设计 错题本.md","filePath":"综合知识/架构设计/架构设计 重要背诵/架构设计 错题本.md","lastUpdated":null}'),r={name:"综合知识/架构设计/架构设计 重要背诵/架构设计 错题本.md"};function a(e,t,i,g,p,c){return n(),o("div",null,[...t[0]||(t[0]=[l(`<hr><p><strong>[Q4] 软件架构概念（数据访问逻辑）</strong></p><p>The second function is the（请作答此空）,the processing required to access data.</p><ul><li><strong>A.</strong> data persistence 数据持久化</li><li><strong>B.</strong> data access objects 数据访问对象</li><li><strong>C.</strong> database connection 数据库连接</li><li><strong>D.</strong> data access logic 数据访问逻辑</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>题干翻译：<strong>第二个功能是 ___，即访问数据所需的处理。</strong></p><p>答案是 <strong>D. data access logic（数据访问逻辑）</strong>。</p><h3 id="这个题的关键-知道「三个功能」是哪三个" tabindex="-1">这个题的关键：知道「三个功能」是哪三个 <a class="header-anchor" href="#这个题的关键-知道「三个功能」是哪三个" aria-label="Permalink to &quot;这个题的关键：知道「三个功能」是哪三个&quot;">​</a></h3><p>这道题来自一组连续题（Q11-Q14），描述应用系统的 <strong>三个核心功能层</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 数据存储（data storage）  </span></span>
<span class="line"><span>    → 存数据、取数据                       ← Q11</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 数据访问逻辑（data access logic）       ← 本题（Q4/Q12）  </span></span>
<span class="line"><span>    → 访问数据所需的处理逻辑  </span></span>
<span class="line"><span>      （查哪个表、怎么 join、where 条件拼装等）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 应用逻辑（application logic）  </span></span>
<span class="line"><span>    → DFD、用例、功能需求中描述的业务逻辑   ← Q13</span></span></code></pre></div><p><strong>数据访问逻辑</strong> 是介于&quot;纯存储&quot;和&quot;业务逻辑&quot;之间的中间层——它知道<strong>怎么去拿数据</strong>，但不负责业务规则。</p><h3 id="其他选项为什么错" tabindex="-1">其他选项为什么错？ <a class="header-anchor" href="#其他选项为什么错" aria-label="Permalink to &quot;其他选项为什么错？&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">分析</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. data persistence 数据持久化</strong></td><td style="text-align:left;">是一种机制/能力，而不是&quot;处理&quot;。题干问的是 <strong>processing（处理）</strong>，而非存储机制</td></tr><tr><td style="text-align:left;"><strong>B. data access objects 数据访问对象</strong></td><td style="text-align:left;">是<strong>实现模式</strong>（DAO 模式），是一种编码层面的设计，不是架构层面的三大功能之一</td></tr><tr><td style="text-align:left;"><strong>C. database connection 数据库连接</strong></td><td style="text-align:left;">是底层连接管理，属于基础设施，不是数据访问的&quot;处理逻辑&quot;</td></tr><tr><td style="text-align:left;"><strong>D. data access logic ✅</strong></td><td style="text-align:left;">正确定义：数据访问所需的处理过程（拼 SQL、ORM 查询、结果映射等）</td></tr></tbody></table><h3 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><p>很多人看到&quot;访问数据&quot;就选 DAO（数据访问对象），但 <strong>DAO 是设计模式</strong>，而题目问的是<strong>系统软件架构的三个基本功能</strong>是什么——这在经典的架构设计教材中是固定三件套：</p><p><strong>Data Storage → Data Access Logic → Application Logic</strong></p></div></details><hr><p><strong>[Q6] 软件架构概念（错误描述）</strong></p><p>以下关于软件架构设计活动的描述，错误的是（）</p><ul><li><strong>A.</strong> 在建立软件架构的初期，一般需要选择一个合适的架构风格</li><li><strong>B.</strong> 将架构分析阶段已标识的构件映射到架构中，并分析这些构件之间的关系</li><li><strong>C.</strong> 软件架构设计活动将已标构件集成到软件架构中，设计并实现这些构件</li><li><strong>D.</strong> 一旦得到了详细的软件架构设计，需要邀请独立于系统开发的外部人员对系统进行评审</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>逐项分析</p><p>注意一下题干，这里是说：【软件架构设计活动】，那么选项需要找出设计活动错误的描述。</p><p>❌ C. 软件架构设计活动将已标构件集成到软件架构中，设计并实现这些构件</p><p><strong>错在哪？</strong> ——「实现」这两个字。</p><p>架构设计活动的边界是<strong>设计</strong>，不包含<strong>实现</strong>（编码/开发）。把构件设计出来、定义接口、描述交互——这是架构设计的事。但写代码实现构件是<strong>开发阶段</strong>的事。</p><p>完整的架构设计活动三步是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 提出架构模型 / 选架构风格  </span></span>
<span class="line"><span>② 产生架构设计（构件映射 + 关系分析）  </span></span>
<span class="line"><span>③ 设计评审</span></span>
<span class="line"><span></span></span>
<span class="line"><span>—— 到设计评审为止。实现？那是下游的事。</span></span></code></pre></div><p>✅ A. 在建立软件架构的初期，一般需要选择一个合适的架构风格</p><p>正确。架构风格（分层、微服务、事件驱动、管道-过滤器等）是顶层决策，初期必须选。</p><p>✅ B. 将架构分析阶段已标识的构件映射到架构中，并分析这些构件之间的关系</p><p>正确。这是架构设计的核心工作——<strong>构件映射 + 关系分析</strong>。</p><p>✅ D. 一旦得到了详细的软件架构设计，需要邀请独立于系统开发的外部人员对系统进行评审</p><p>正确。架构评审要求<strong>独立的外部专家</strong>参与，这是保证架构质量的关键手段。</p><hr><p>考点提炼</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构设计活动 = 建模 + 设计 + 评审  </span></span>
<span class="line"><span>                ↓  </span></span>
<span class="line"><span>          不包含「实现」</span></span></code></pre></div><p><strong>易错提醒</strong>：题目把「设计并实现」放在一起，很多人扫过去没注意&quot;实现&quot;两个字就选了。记住：<strong>架构师管设计，开发工程师管实现。</strong></p></div></details><hr><hr><p><strong>[Q8] 软件架构概念</strong></p><p>在构件组装过程中需要检测并解决架构失配问题。其中 （1） 失配主要包括由于系统对构件基础设施、控制模型和数据模型的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>区分这两个题目的关键在于理解<strong>架构失配</strong>中“构件”和“连接子”各自关注的冲突类型。</p><ul><li><strong>构件失配</strong>（Q8）：源于<strong>构件自身</strong>的假设冲突，例如对底层基础设施（操作系统、中间件）、控制模型（同步/异步、调用方式）或数据模型（数据结构、类型系统）的假设不一致。这些属于构件内部或构件与环境的固有属性差异。</li><li><strong>连接子失配</strong>（Q9）：源于<strong>构件之间交互</strong>的假设冲突，例如交互协议（消息顺序、超时机制、事务边界）或连接时数据格式（序列化格式、字节序、编码）不一致。这些属于连接线（即连接子）上需要协调的规则与格式差异。</li></ul><p><strong>记忆技巧</strong>：</p><ul><li>看到“基础设施、控制模型、数据模型” → 选<strong>构件</strong>（构件自身特征）。</li><li>看到“交互协议、数据格式” → 选<strong>连接子</strong>（构件间通信细节）。</li></ul></div></details><hr><p><strong>[Q9] 软件架构概念</strong></p><p>（2） 失配包括由于系统对构件交互协议、构件连接时数据格式的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p>The architecture design specifies the overall architecture and the placement of software and hardware that will be used. Architecture design is a very complex process that is often left to experienced architecture designers and consultants.</p><p>The first step is to refine the (1) into more detailed requirements that are then employed to help select the architecture to be used and the software components to be placed on each device. In a (2), one also has to decide whether to use a two-tier, three-tier, or n-tier architecture. Then the requirements and the architect design are used to develop the hardware and software specification. There are four primary types of nonfunctional requirements that can be important in designing the architecture: (3) specify the operating environment(s) in which the system must perform and how those may change over time. (4) focus on the nonfunctional requirements issues such as response time, capacity, and reliability. (5) are the abilities to protect the information system from disruption and data loss, whether caused by an intentional act. Cultural and political requirements are specific to the countries in which the system will be used.</p><p><strong>[Q16] 软件架构概念（非功能性需求：第一步）</strong></p><p>The first step is to refine the （1） into more detailed requirements.</p><ul><li><strong>A.</strong> functional requirements</li><li><strong>B.</strong> nonfunctional requirements</li><li><strong>C.</strong> system constraint</li><li><strong>D.</strong> system operational environment</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>翻译：</p><p>架构设计规定了整体架构以及将要使用的软件和硬件的部署位置。架构设计是一个非常复杂的过程，通常由经验丰富的架构设计师和顾问完成。第一步是将（1）细化为更详细的需求，然后用于帮助选择要使用的架构以及部署在每台设备上的软件组件。在（2）中，还需要决定使用两层、三层还是 n 层架构。然后，利用这些需求和架构设计来制定硬件和软件规格说明。在设计架构时，有四类主要的非功能性需求可能非常重要：（3）规定了系统必须运行的操作环境以及这些环境随时间可能发生的变化。（4）关注响应时间、容量和可靠性等非功能性需求问题。（5）是指保护信息系统免受中断和数据丢失的能力，无论这些中断或丢失是由故意行为引起的。文化和政治需求则是系统使用所在国家/地区特有的需求。</p></div></details><hr><p><strong>[Q17] 软件架构概念（C/S架构）</strong></p><p>In a （2）, one also has to decide whether to use a two-tier, three-tier, or n-tier architecture.</p><ul><li><strong>A.</strong> client-based architecture</li><li><strong>B.</strong> server-based architecture</li><li><strong>C.</strong> network architecture</li><li><strong>D.</strong> client-server architecture</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>根据上下文，这里讨论的是<strong>客户端-服务器架构</strong>（client-server architecture），因为两层、三层和 n 层架构都是其具体实现形式。因此正确答案是 <strong>D</strong>。</p></div></details><hr><p><strong>[Q18] 软件架构概念（操作性需求）</strong></p><p>（3） specify the operating environment(s) in which the system must perform.</p><ul><li><strong>A.</strong> Operational requirements</li><li><strong>B.</strong> Speed requirement</li><li><strong>C.</strong> Access control requirements</li><li><strong>D.</strong> Customization requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>根据上下文，描述“指定系统必须运行的操作环境及其随时间的变化”的正是<strong>操作需求（Operational requirements）</strong>。因此正确答案是 <strong>A</strong>。</p><p>其他选项：速度需求、访问控制需求、定制化需求都不匹配。</p></div></details><hr><p><strong>[Q19] 软件架构概念（性能需求）</strong></p><p>（4） focus on the nonfunctional requirements issues such as response time, capacity, and reliability.</p><ul><li><strong>A.</strong> Environment requirements</li><li><strong>B.</strong> Maintainability requirements</li><li><strong>C.</strong> Performance requirements</li><li><strong>D.</strong> Virus control requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据描述，关注响应时间、容量、可靠性等非功能性需求问题，正是<strong>性能需求（Performance requirements）</strong>。因此正确答案是 <strong>C</strong></p><p>其他选项</p><ul><li><strong>A. Environment requirements（环境需求）</strong><br> 关注系统运行所需的物理或软件环境，例如操作系统版本、网络带宽、硬件配置、温度湿度等。它不直接涉及响应时间、容量或可靠性。</li><li><strong>B. Maintainability requirements（可维护性需求）</strong><br> 关注系统便于修改、修复、升级的程度，例如模块化程度、日志记录、诊断接口等。与响应时间、容量没有直接关系。</li><li><strong>D. Virus control requirements（病毒控制需求）</strong><br> 属于安全需求的一类，侧重于防病毒、恶意软件检测与清除等。与性能指标（响应时间、容量、可靠性）不同。</li></ul></div></details><hr><p><strong>[Q20] 软件架构概念（安全性需求）</strong></p><p>（5） are the abilities to protect the information system from disruption and data loss.</p><ul><li><strong>A.</strong> Safety requirements</li><li><strong>B.</strong> Security requirements</li><li><strong>C.</strong> Data management requirements</li><li><strong>D.</strong> System requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>根据题干描述：“保护信息系统免受中断和数据丢失的能力”，这明确指的是<strong>安全需求（Security requirements）</strong>。因此正确答案是 <strong>B</strong>。</p><p>其他选项解释：</p><ul><li><strong>A. Safety requirements（安全需求）</strong><br> 通常指<strong>人身安全</strong>或<strong>设备安全</strong>（如防止触电、机械伤害、防火等），与信息系统的数据丢失和中断防护不是同一概念。</li><li><strong>C. Data management requirements（数据管理需求）</strong><br> 侧重于数据的存储、备份、归档、生命周期管理等，不直接涵盖防护中断和故意破坏的能力。</li><li><strong>D. System requirements（系统需求）</strong><br> 范围太宽，包含功能性和非功能性需求，不能特指防护中断和数据丢失的能力。</li></ul><p>因此，正确答案是 <strong>B</strong>。</p></div></details><hr><p><strong>[Q23] 软件架构概念（ES vs 一般系统）</strong></p><p>专家系统（ES）与一般计算机系统的根本区别在于 （ ） 。</p><ul><li><strong>A.</strong> 处理数字与符号</li><li><strong>B.</strong> 处理确定性知识</li><li><strong>C.</strong> 解释推理过程</li><li><strong>D.</strong> 操作成本低廉</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q24] 软件架构概念（DSS）</strong></p><p>决策支持系统（DSS）主要用于解决 （ ） 。</p><ul><li><strong>A.</strong> 结构化问题</li><li><strong>B.</strong> 半结构化问题</li><li><strong>C.</strong> 日常事务处理</li><li><strong>D.</strong> 纯数据存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>DSS的定义：决策支持系统主要用于解决半结构化和非结构化问题，而非结构化问题。通常教材中说DSS解决半结构化问题。选项：A结构化问题（由MIS或TPS处理），B半结构化问题，C日常事务处理（TPS），D纯数据存储（数据库）。所以选B。</p><p>决策支持系统（DSS）主要辅助解决<strong>半结构化问题</strong>（如销售预测、预算规划等），这类问题既有一定的规律可循，又需要人的判断和灵活性。结构化问题通常由管理信息系统（MIS）或事务处理系统（TPS）处理；日常事务处理和纯数据存储则不属于DSS的核心定位。</p></div></details><hr><p><strong>[Q26] 软件架构概念（设计阶段排除）</strong></p><p>在设计阶段，软件架构设计的研究主要不包括 （ ） 。</p><ul><li><strong>A.</strong> 软件架构模型的描述</li><li><strong>B.</strong> 软件架构模型的设计与分析方法</li><li><strong>C.</strong> 对软件架构设计经验的总结与复用</li><li><strong>D.</strong> 从现有系统中获得需要的构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>软件架构设计阶段的研究重点包括：</p><ul><li><strong>A. 软件架构模型的描述</strong>（如架构视图、风格、模式）</li><li><strong>B. 软件架构模型的设计与分析方法</strong>（如质量属性场景、架构权衡分析方法）</li><li><strong>C. 对软件架构设计经验的总结与复用</strong>（如架构模式、参考架构）</li></ul><p>而 <strong>D. 从现有系统中获得需要的构件</strong> 更侧重于<strong>软件复用</strong>或<strong>构件获取</strong>，通常属于实现、集成或构件库管理阶段，不是架构设计阶段的核心研究内容。因此，该项不包括在内。</p></div></details><hr><p><strong>[Q28] 软件架构概念（实现阶段研究）</strong></p><p>在软件架构的实现阶段研究中，以下哪项不属于主要研究方向（ ）。</p><ul><li><strong>A.</strong> 基于软件架构的开发过程支持</li><li><strong>B.</strong> 从软件架构向实现过渡的途径</li><li><strong>C.</strong> 基于软件架构的测试技术</li><li><strong>D.</strong> 软件架构的多视图表示</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>软件架构的实现阶段主要关注如何将架构设计转化为可运行的系统，包括：</p><ul><li><strong>A. 基于软件架构的开发过程支持</strong>（如迭代开发、架构驱动的开发流程）</li><li><strong>B. 从软件架构向实现过渡的途径</strong>（如架构映射、代码生成）</li><li><strong>C. 基于软件架构的测试技术</strong>（如架构符合性测试、构件集成测试）</li></ul><p>而 <strong>D. 软件架构的多视图表示</strong>（如逻辑视图、物理视图等）属于<strong>架构描述与设计阶段</strong>的研究内容，用于表达和沟通架构设计，而非实现阶段的核心方向。因此，该项不属于实现阶段的主要研究。</p></div></details><hr><p><strong>[Q29] 软件架构概念（需求→架构转换）</strong></p><p>在软件架构设计的需求阶段，关于需求模型向软件架构模型转换的主要关注点是（）。</p><ul><li><strong>A.</strong> 如何描述软件架构模型</li><li><strong>B.</strong> 如何分析软件架构质量属性</li><li><strong>C.</strong> 如何构建软件架构模型和保证可追踪性</li><li><strong>D.</strong> 如何选择合适的部署方案</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p><strong>解析</strong>：</p><p>在软件架构设计的需求阶段，核心任务是<strong>从需求模型（如用例、质量属性场景、约束）过渡到架构模型</strong>。这个转换过程中，主要关注两点：</p><ol><li><strong>如何构建软件架构模型</strong>：即如何将功能需求和非功能需求映射为构件、连接子、配置等架构元素。</li><li><strong>保证可追踪性</strong>：确保每个架构决策都能回溯到具体需求（尤其是质量属性场景），以便后续验证、评估和变更管理。</li></ol><ul><li><strong>A</strong>（如何描述软件架构模型）属于<strong>设计阶段</strong>的表示问题，而不是转换的关注点。</li><li><strong>B</strong>（如何分析软件架构质量属性）属于<strong>设计阶段</strong>的评估方法，是在模型构建之后进行。</li><li><strong>D</strong>（如何选择合适的部署方案）属于<strong>部署阶段</strong>的活动。</li></ul><p>因此，<strong>C</strong> 最准确地描述了需求阶段向架构模型转换时的核心关注点。</p></div></details><hr><p><strong>[Q32] 软件架构概念（重用设计经验）</strong></p><p>在软件体系结构设计中，用于总结和重用设计经验的主要技术包括（）。</p><ul><li><strong>A.</strong> 设计模式和框架</li><li><strong>B.</strong> 体系结构风格和DSSA</li><li><strong>C.</strong> UML图和原型设计</li><li><strong>D.</strong> 代码重构和单元测试</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><strong>解析</strong>：</p><p>在软件体系结构设计中，总结和重用设计经验的主要技术包括：</p><ul><li><p><strong>体系结构风格</strong>（如分层、管道-过滤器、事件驱动等）是对一类相似问题的通用解决方案模板，可复用架构经验。</p></li><li><p><strong>DSSA（特定领域软件架构）</strong> 是针对特定领域（如航空、金融、医疗）总结出的参考架构，支持在该领域内大规模重用设计经验。</p></li><li><p><strong>A</strong>（设计模式和框架）更偏向<strong>详细设计</strong>和<strong>实现</strong>层面的重用，虽然也涉及经验总结，但不是最高层次的<strong>体系结构</strong>重用技术。</p></li><li><p><strong>C</strong>（UML图和原型设计）是建模和验证手段，并非专门用于总结和重用设计经验。</p></li><li><p><strong>D</strong>（代码重构和单元测试）属于<strong>实现与测试</strong>阶段的活动，与设计经验总结无关。</p></li></ul><p>因此，<strong>B</strong> 最符合题意。</p></div></details>`,78)])])}const m=s(r,[["render",a]]);export{d as __pageData,m as default};
